def strlen(string: str) -> int:
    count = 0
    escape_chars = ['\n', '\t', '\r', '\f', '\v', '\\', '\'', '\"']

    i = 0
    while i < len(string):
        if string[i] == '\\':
            if i+1 < len(string) and string[i+1] in escape_chars:
                count += 1
                i += 1
        else:
